/**
 * Alberto Medaglia's portrait — the REAL client photo delivered by the client
 * (public/images/alberto-medaglia.png, never modified). Resized derivatives are generated by
 * scripts/make-portrait-derivatives.mjs (resize only; crops are CSS object-position).
 *
 * NOTE: this is a presentation asset only. The registry slot `facts.photo` (R14) was
 * resolved separately in src/content/facts.ts (agency owner, 2026-10-19; emits Person.image).
 * The portrait is never used as og:image (I1 stays open).
 * Alt text: name only — Alberto's title is unconfirmed (I2).
 */
export const PORTRAIT = {
  alt: 'Alberto Medaglia',
  width: 1385,
  height: 1136,
  fallback: '/images/alberto-medaglia-960.jpg',
  widths: [640, 960, 1385],
  base: '/images/alberto-medaglia',
} as const;

export const portraitSrcset = (ext: 'avif' | 'webp' | 'jpg'): string =>
  PORTRAIT.widths.map((w) => `${PORTRAIT.base}-${w}.${ext} ${w}w`).join(', ');
